export function validateJournalOrder(value){if(!Array.isArray(value)||value.length>10000||value.some(id=>typeof id!=='string'||!/^[a-z0-9_-]{1,100}$/i.test(id))||new Set(value).size!==value.length)throw Error('Invalid journal order.');return [...value];}
export function orderPlaces(records,order=[]){const ranks=new Map(order.map((id,i)=>[id,i]));return records.slice().sort((a,b)=>(ranks.get(a.id)??order.length)-(ranks.get(b.id)??order.length));}
export function movePlace(ids,from,to){const out=[...ids],index=out.indexOf(from),target=out.indexOf(to);if(index<0||target<0)return out;out.splice(index,1);out.splice(target,0,from);return out;}
export function createReorderUI({document,getRecords,getOrder,save,onStatus,confirm=globalThis.confirm,art}){
 const $=id=>document.getElementById(id);let ids=[],baseline='[]',busy=false,drag=null,hold=null,query='';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function render(){const rows=new Map(getRecords().map(r=>[r.id,r]));ids=ids.filter(id=>rows.has(id));for(const id of rows.keys())if(!ids.includes(id))ids.push(id);$('reorder-list').innerHTML=ids.filter(id=>!query||rows.get(id).title.toLocaleLowerCase().includes(query)).map(id=>{const r=rows.get(id);return `<div class="reorder-row" data-order-id="${id}"><button type="button" class="order-grip" data-order-grip="${id}" aria-label="Hold to move ${esc(r.title)}" aria-pressed="false">⠿</button><img src="${esc(art(r))}" alt="" draggable="false"><span>${esc(r.title)}</span><button type="button" class="text-button" data-order-up="${id}" aria-label="Move ${esc(r.title)} up">↑</button><button type="button" class="text-button" data-order-down="${id}" aria-label="Move ${esc(r.title)} down">↓</button></div>`;}).join('')||'<p class="field-help">No footprints in this selection.</p>';$('reorder-controls').inert=busy;$('reorder-save').disabled=busy||JSON.stringify(ids)===baseline;}
 function moved(id,direction){if(busy)return;const index=ids.indexOf(id),to=Math.max(0,Math.min(ids.length-1,index+direction));if(index===to)return;ids=movePlace(ids,id,ids[to]);render();document.querySelector(`[data-order-${direction<0?'up':'down'}="${id}"]`)?.focus({preventScroll:true});$('reorder-status').textContent='Order changed. Save order to keep it.';}
 function finish(cancel=false){clearTimeout(hold);hold=null;if(!drag)return;if(cancel)ids=drag.before;drag=null;render();}
 function wire(){
  $('reorder-query').oninput=e=>{query=e.target.value;render();};$('reorder-list').addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.orderUp)moved(b.dataset.orderUp,-1);if(b?.dataset.orderDown)moved(b.dataset.orderDown,1);});
  const list=$('reorder-list');list.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-order-grip]');if(!b||busy||e.button!==0)return;const id=b.dataset.orderGrip;drag={id,pointer:e.pointerId,x:e.clientX,y:e.clientY,active:false,before:[...ids]};list.setPointerCapture(e.pointerId);hold=setTimeout(()=>{if(!drag)return;drag.active=true;list.classList.add('order-dragging');list.querySelector(`[data-order-id="${id}"]`)?.classList.add('moving');navigator.vibrate?.(15);$('reorder-status').textContent='Move to a footprint to change its position. Release to place it.';},350);});
  list.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointer)return;if(!drag.active){if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>10)finish(true);return;}e.preventDefault();const rows=[...list.querySelectorAll('[data-order-id]')],target=rows.find(row=>{const r=row.getBoundingClientRect();return e.clientY>=r.top&&e.clientY<=r.bottom;});if(target&&target.dataset.orderId!==drag.id){ids=movePlace(ids,drag.id,target.dataset.orderId);render();list.classList.add('order-dragging');list.querySelector(`[data-order-id="${drag.id}"]`)?.classList.add('moving');}
   const modal=$('reorder'),rect=modal.getBoundingClientRect();if(e.clientY<rect.top+85)modal.scrollTop-=12;else if(e.clientY>rect.bottom-85)modal.scrollTop+=12;
  });for(const type of ['pointerup','pointercancel','lostpointercapture'])list.addEventListener(type,()=>{list.classList.remove('order-dragging');finish(type!=='pointerup');});
  $('reorder-save').onclick=async()=>{if(busy)return;busy=true;render();try{await save(validateJournalOrder(ids));baseline=JSON.stringify(ids);$('reorder-status').textContent='Order saved. Your journal now uses My order.';}catch(e){$('reorder-status').textContent='Order not saved. '+e.message;onStatus('Your saved order has not changed. Try Save order again.');}finally{busy=false;render();}};
 }
 return {wire,open(){query='';$('reorder-query').value='';ids=orderPlaces(getRecords(),getOrder()).map(r=>r.id);baseline=JSON.stringify(ids);$('reorder-status').textContent='';render();},canClose(){if(busy){onStatus('Saving your order. Please wait.');return false;}return JSON.stringify(ids)===baseline||confirm('Discard your unsaved footprint order? Your journal will stay.');},hasPending:()=>busy||JSON.stringify(ids)!==baseline,reset(){finish(true);ids=[];baseline='[]';}};
}
